void
CsrNetLayer::SendNeighborCheck (
  CsrNodeId neighbor,
  CsrNeighborCheckType type,
  CsrNodeId target,
  uint32_t discoverySequence)
{
  if (m_hop == nullptr)
    {
      return;
    }

  Ptr<Packet> p = Create<Packet> ();

  CsrHelloHeader hh;
  hh.SetNodeId (m_nodeId);
  hh.SetHelloSeq (++m_neighborCheckSeq);
  hh.SetSpeedKey (m_minSpeedKey);

  hh.SetNodeType (m_nodeType);

  double s0PowerDbm = m_rxS0BaseLevelDbm + m_linkMarginDb;
  hh.SetRxPowerDbmX10 (
    static_cast<int16_t> (std::round (s0PowerDbm * 10.0)));

  if (type == CsrNeighborCheckType::Discovery &&
      m_arlNeighborAdmissionEnabled)
    {
      // CHECK_DISCOVERY carries the sender's neighbor state byte.  The
      // legacy value is NEIGHBOR_ACTIVE == 3, not the global node count used
      // by ordinary HELLOs.
      hh.SetActiveNodes (
        IsArlNeighborActive (neighbor) ? 3 : 0);
    }
  else
    {
      hh.SetActiveNodes (
        static_cast<uint8_t> (GetActiveNodeCount ()));
    }

  hh.SetArlRouteMsgType (
    CsrArlRouteMsgType::NeighborCheck);

  hh.SetNeighborCheckType (type);
  hh.SetNeighborCheckTarget (target);
  hh.SetDiscoverySequence (discoverySequence);
  hh.ClearAdvertisedRoutes ();

  p->AddHeader (hh);
  std::cout << "[NWK " << m_nodeId
            << "] Sending targeted ARL NeighborCheck"
            << " neighbor=" << neighbor
            << " subtype=" << NeighborCheckTypeName (type);

  if (type == CsrNeighborCheckType::NoPath)
    {
      std::cout << " unreachableDest=" << target;
    }

  if (type == CsrNeighborCheckType::Discovery ||
      type == CsrNeighborCheckType::Verify)
    {
      std::cout << " discoverySequence=" << discoverySequence;
    }

  std::cout << std::endl;

  m_hop->SendNeighborCheck (neighbor, p);
}

CsrHopLayer::SendNeighborCheck (CsrNodeId dst, Ptr<Packet> payload)
{
  NS_ASSERT (m_mac != nullptr);

  CsrHelloHeader neighborCheckMetadata;
  bool neighborCheckMetadataValid =
    payload != nullptr && payload->PeekHeader (neighborCheckMetadata);

  uint32_t rawPayloadSize = payload->GetSize ();
  if (neighborCheckMetadataValid)
    {
      Ptr<Packet> rawPayload = payload->Copy ();
      rawPayload->RemoveHeader (neighborCheckMetadata);
      rawPayloadSize = rawPayload->GetSize ();
    }

  uint16_t &lastSeq = m_lastSentSeqByDest[dst];
  uint16_t seq = static_cast<uint16_t> ((lastSeq + 1) & 0xFFFF);
  lastSeq = seq;

  CsrHeader hdr (m_nodeId,
                 dst,
                 seq,
                 7,     // robust control priority
                 true,  // ACKable
                 false);

  hdr.SetType (CSR_PKT_NEIGHBOR_CHECK);
  hdr.SetDestType (CSR_DEST_UNICAST);
  hdr.SetSecurityCount (m_hopSecurity.GetOwnSecurityCount ());
  ApplyLinkControl (hdr, {dst});

  // packetTypes.c maps NeighborCheck (packet type 9) to Pairwise16. Protect
  // once here so every HOP retry reuses the original pairwise key/sequence.
  Ptr<Packet> frame = ProtectPairwisePayload (
    dst,
    CsrPairwiseSecurityMode::Pairwise16,
    LEGACY_NEIGHBOR_CHECK_PACKET_TYPE,
    payload);
  frame->AddHeader (hdr);
  CsrSetOpnetEnvelope (
    frame,
    CsrOpnetPacketFormat::Routes,
    CsrOpnetPacketModel::GetFixedSizeBytes (
      CsrOpnetPacketFormat::Routes) +
      LEGACY_NEIGHBOR_CHECK_SECURITY_OVERHEAD +
      rawPayloadSize);

  EnqueueResend (
    dst,
    seq,
    frame->Copy (),
    false);

  ResendEntry *resendEntry = FindResendEntry (dst, seq);
  if (resendEntry != nullptr && neighborCheckMetadataValid)
    {
      resendEntry->neighborCheckMetadataValid = true;
      resendEntry->neighborCheckType =
        neighborCheckMetadata.GetNeighborCheckType ();
      resendEntry->neighborCheckDiscoverySequence =
        neighborCheckMetadata.GetDiscoverySequence ();
    }

  std::cout << "[HOP " << m_nodeId
            << "] TX reliable NeighborCheck to " << dst
            << " seq=" << seq
            << std::endl;

  m_mac->EnqueueTxFrame (frame,
                         dst,
                         7,
                         true);
}

